#include <map>
#include <iostream>
#include <string>

int main() {
    std::map<std::string, int> coll = {{"otto", 7}};

    // Pitfall: Misspelling 'otto' as 'ottto'
    std::cout << coll.size() << "\n"; // Output: 1

    // This inserts {"ottto", 0} and prints 0
    std::cout << coll["ottto"] << "\n"; 

    // Map size has increased unintentionally
    std::cout << coll.size() << "\n"; // Output: 2

    // Safer read-only access:
    try {
        std::cout << coll.at("missing") << "\n";
    } catch (const std::out_of_range& e) {
        // Handles error without modifying coll
    }
}
